`,(0,r.jsxs)(i.ul,{children:[`
`,(0,r.jsx)(i.li,{children:"Which of the six prompting techniques do you think would most enhance your current AI interactions?"}),`
`,(0,r.jsx)(i.li,{children:"Think of a recent AI interaction that didn't meet your needs. Which techniques might have improved the outcome?"}),`
`,(0,r.jsx)(i.li,{children:"How does understanding these prompting techniques connect to the Description competency from the AI Fluency Framework?"}),`
